import React, { useState, useEffect } from 'react';
import { Job } from './types';
import { searchAndParseJobs, analyzeJob, generateApplicationKit } from './services/geminiService';
import { initFirebase, subscribeToJobs, addOrUpdateJob, updateJobStatus, deleteJob, saveAnalysis } from './services/firebase';
import JobCard from './components/JobCard';
import StatsPanel from './components/StatsPanel';
import CoverLetterModal from './components/CoverLetterModal';
import { Zap, RefreshCw, Filter, Database, CloudLightning, Settings, Briefcase, Search } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'new' | 'applied'>('new');
  const [allJobs, setAllJobs] = useState<Job[]>([]);
  const [isDbConnected, setIsDbConnected] = useState(false);
  const [configInput, setConfigInput] = useState('');
  const [cityFilter, setCityFilter] = useState<string>('All');
  const [sortBy, setSortBy] = useState<'Score' | 'Date'>('Score');
  const [isFetching, setIsFetching] = useState(false);
  const [analyzingCount, setAnalyzingCount] = useState(0);
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [kitContent, setKitContent] = useState("");
  const [isGeneratingKit, setIsGeneratingKit] = useState(false);

  const hasApiKey = !!import.meta.env.VITE_API_KEY;

  useEffect(() => {
    const savedConfig = localStorage.getItem('firebase_config');
    if (savedConfig) {
      try {
        const config = JSON.parse(savedConfig);
        if (initFirebase(config)) {
          setIsDbConnected(true);
        }
      } catch (e) { console.error("Invalid saved config", e); }
    }
  }, []);

  useEffect(() => {
    if (isDbConnected) {
      const unsubscribe = subscribeToJobs(setAllJobs);
      return () => unsubscribe();
    }
  }, [isDbConnected]);

  const handleConnectDb = () => {
    try {
      const cleanInput = configInput.replace(/const firebaseConfig = /, '').replace(/;$/, '');
      const config = JSON.parse(cleanInput);
      if (initFirebase(config)) {
        localStorage.setItem('firebase_config', JSON.stringify(config));
        setIsDbConnected(true);
      } else { alert("Failed to initialize Firebase."); }
    } catch (e) { alert("Invalid JSON Format."); }
  };

  const fetchJobs = async () => {
    if (!isDbConnected) return;
    setIsFetching(true);
    const query = `("Product Designer" OR "UX Designer" OR "UI Designer") "United Kingdom" -Intern -Trainee -Apprentice (site:linkedin.com/jobs OR site:reed.co.uk OR site:glassdoor.co.uk OR site:totaljobs.com OR site:otta.com OR site:civilservicejobs.service.gov.uk OR site:ifyoucouldjobs.com OR site:designweek.co.uk OR site:cwjobs.co.uk)`;
    try {
      const foundJobs = await searchAndParseJobs(query);
      const jobsToAnalyze: Job[] = [];
      const currentJobsMap = new Map(allJobs.map(j => [j.id, j]));
      for (const job of foundJobs) {
        const docId = `${job.title}_${job.company}`.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 100);
        await addOrUpdateJob(job);
        if (!currentJobsMap.has(docId) || !currentJobsMap.get(docId)?.analysis) {
          jobsToAnalyze.push({ ...job, id: docId });
        }
      }
      if (jobsToAnalyze.length > 0) analyzeNewJobs(jobsToAnalyze);
    } catch (error) { console.error(error); }
    setIsFetching(false);
  };

  const analyzeNewJobs = async (jobs: Job[]) => {
    setAnalyzingCount(jobs.length);
    for (const job of jobs) {
      try {
        const analysis = await analyzeJob(job);
        await saveAnalysis(job.id, analysis);
      } catch (e) { console.error(`Analysis failed for job ${job.id}`, e); }
      setAnalyzingCount(prev => prev - 1);
      await new Promise(resolve => setTimeout(resolve, 4000));
    }
  };

  const handleDraftKit = async (job: Job) => {
    if (!job.analysis) return;
    setSelectedJob(job);
    setModalOpen(true);
    setKitContent("");
    setIsGeneratingKit(true);
    const content = await generateApplicationKit(job, job.analysis);
    setKitContent(content);
    setIsGeneratingKit(false);
  };

  const availableLocations = ['All', ...Array.from(new Set(allJobs.map(j => j.location.split(',')[0].trim())))];
  const filteredJobs = allJobs.filter(j => j.status !== activeTab ? false : (cityFilter === 'All' ? true : j.location.includes(cityFilter)));
  const sortedJobs = [...filteredJobs].sort((a, b) => sortBy === 'Score' ? (b.analysis?.score || 0) - (a.analysis?.score || 0) : 0);

  if (!hasApiKey) return <div>API Key Missing</div>;
  if (!isDbConnected) return (
    <div>
        <h1>Connect Cloud Database</h1>
        <textarea value={configInput} onChange={(e) => setConfigInput(e.target.value)} placeholder="Paste Firebase Config JSON here" />
        <button onClick={handleConnectDb}>Initialize System</button>
    </div>
  );

  return (
    <div className="min-h-screen bg-[#f3f4f6]">
      {/* Header and Dashboard UI */}
      <h1>Vyom's Job Agent</h1>
      <button onClick={fetchJobs} disabled={isFetching}>{isFetching ? 'Scouting...' : 'Scout Now'}</button>
      {/* Filters, Tabs, Job List etc. */}
      <div className="space-y-4 p-4">
        {sortedJobs.map(job => (
          <JobCard 
            key={job.id} 
            job={job} 
            onGenerateKit={handleDraftKit}
            onToggleStatus={(id, status) => updateJobStatus(id, status === 'new' ? 'applied' : 'new')}
            onDelete={deleteJob}
          />
        ))}
      </div>
      <CoverLetterModal 
        isOpen={modalOpen} 
        onClose={() => setModalOpen(false)} 
        job={selectedJob}
        content={kitContent}
        isGenerating={isGeneratingKit}
      />
    </div>
  );
};
export default App;
