import { initializeApp, FirebaseApp } from "firebase/app";
import { getFirestore, collection, doc, setDoc, onSnapshot, updateDoc, deleteDoc, Firestore } from "firebase/firestore";
import { Job } from "../types";
import { FirebaseConfig } from "../constants";

let app: FirebaseApp | null = null;
let db: Firestore | null = null;

export const initFirebase = (config: FirebaseConfig) => {
  try {
    if (!app) {
      app = initializeApp(config);
      db = getFirestore(app);
    }
    return !!db;
  } catch (e) {
    console.error("Firebase initialization failed:", e);
    return false;
  }
};

const getDocId = (job: Job) => `${job.title}_${job.company}`.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 100);

export const subscribeToJobs = (onData: (jobs: Job[]) => void) => {
  if (!db) return () => {};
  return onSnapshot(collection(db, "jobs"), (snapshot) => {
    onData(snapshot.docs.map(doc => doc.data() as Job));
  });
};

export const addOrUpdateJob = async (job: Job) => {
  if (!db) return;
  const docId = getDocId(job);
  await setDoc(doc(db, "jobs", docId), { ...job, id: docId }, { merge: true });
};

export const updateJobStatus = async (jobId: string, status: 'new' | 'applied') => {
  if (!db) return;
  await updateDoc(doc(db, "jobs", jobId), { status });
};

export const saveAnalysis = async (jobId: string, analysis: any) => {
  if (!db) return;
  await updateDoc(doc(db, "jobs", jobId), { analysis });
};

export const deleteJob = async (jobId: string) => {
  if (!db) return;
  await deleteDoc(doc(db, "jobs", jobId));
};
```

