        return await fn();
    } catch (error: any) {
        if (retries > 0 && (error?.error?.code === 429 || error?.error?.status === 'RESOURCE_EXHAUSTED')) {
            await new Promise(res => setTimeout(res, delay));
            return retryWithBackoff(fn, retries - 1, delay * 2);
        }
        throw error;
    }
};

export const searchAndParseJobs = async (query: string): Promise<Job[]> => {
  const prompt = `
    ### ROLE DEFINITION
    You are an expert Talent Scout. Your goal is to identify high-quality **Mid-Level, Senior, and Leadership** opportunities.
    ### SEARCH QUERY CONTEXT
    "${query}"
    ### SEARCH STRATEGY
    - Search UK Wide. Prioritize Edinburgh/Glasgow but include all major cities and remote roles.
    - Exclude "Intern", "Apprentice", "Trainee" roles.
    - CRITICAL: Use "Recursive Discovery". Analyze search results for "People also viewed" or "Similar jobs" to find hidden roles.
    ### OUTPUT FORMAT
    Return a JSON array of 8-10 listings inside a markdown code block.
    [{"job_title": "", "company": "", "seniority_score": "Mid|Senior|Lead", "source_url": "", "is_related_job_discovery": false, "summary": "", "posted_date": "", "location": "", "source": ""}]
  `;
  const ai = getClient();
  const response = await retryWithBackoff(() => ai.models.generateContent({ model: "gemini-2.5-flash", contents: prompt, config: { tools: [{ googleSearch: {} }] } }));
  const text = response.text || "[]";
  const jsonMatch = text.match(/```json\n([\s\S]*?)\n```/);
  const rawJobs = JSON.parse(jsonMatch ? jsonMatch[1] : "[]");
  return rawJobs.map((j: any) => ({
      ...j, title: j.job_title, url: j.source_url, isRelatedDiscovery: j.is_related_job_discovery
  }));
};

