import React from 'react';
import { PieChart, Pie, Sector, Cell, Tooltip } from 'recharts';

interface IndustryCount {
    [key: string]: number;
}

interface StatsPanelProps {
    jobs: any[]; // Assuming jobs is an array of objects - adapt as needed
}

const StatsPanel: React.FC<StatsPanelProps> = ({ jobs }) => {
    // Correctly initialize industryCounts as an empty object
    const industryCounts: IndustryCount = jobs.reduce((acc, job) => {
        const industry = job.industry || 'Unknown'; // Ensure industry exists and handles null/undefined
        acc[industry] = (acc[industry] || 0) + 1;
        return acc;
    }, {} as IndustryCount);

    const industryData = Object.entries(industryCounts)
        .filter(([_, value]) => value > 0)
        .sort(([, a], [, b]) => b - a)
        .map(([industry, count]) => ({
            name: industry,
            value: count,
        }));

    const COLORS = ['#8884d8', '#82ca9d', '#ffc658', '#8C564B', '#9467BD', '#e377c2', '#7f7f7f', '#bcbd22', '#17becf']; // Add more colors as needed
    const RADIAN = Math.PI / 180;
    const renderCustomizedLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, index }: any) => {
        const radius = innerRadius + (outerRadius - innerRadius) * 0.5;
        const x = cx + radius * Math.cos(-midAngle * RADIAN);
        const y = cy + radius * Math.sin(-midAngle * RADIAN);

        return (
            <text x={x} y={y} fill="white" textAnchor={x > cx ? 'start' : 'end'} dominantBaseline="central">
                {`${(percent * 100).toFixed(0)}%`}
            </text>
        );
    };

    return (
        <div>
            <PieChart width={400} height={400}>
                <Pie
                    data={industryData}
                    cx={200}
                    cy={200}
                    labelLine={false}
                    label={renderCustomizedLabel}
                    outerRadius={80}
                    fill="#8884d8"
                    dataKey="value"
                >
                    {industryData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                </Pie>
                <Tooltip />
            </PieChart>
        </div>
    );
};

export default StatsPanel;
