    try {
      // 1. Robust extraction: Find the first '{' and last '}'
      const firstBrace = configInput.indexOf('{');
      const lastBrace = configInput.lastIndexOf('}');

      if (firstBrace === -1 || lastBrace === -1) {
         throw new Error("Invalid format. Could not find '{' or '}'.");
      }

      // Extract the object literal string
      const objectString = configInput.substring(firstBrace, lastBrace + 1);

      // 2. Parse the object
      let config;
      try {
        const parseFn = new Function(`return ${objectString};`);
        config = parseFn();
      } catch (e) {
         try {
            config = JSON.parse(objectString);
         } catch (jsonError) {
            console.error("Parse error:", e);
            throw new Error("Could not parse configuration object.");
         }
      }

      if (!config || !config.apiKey || !config.projectId) {
         throw new Error("Missing required Firebase fields (apiKey, projectId)");
      }

      const success = initFirebase(config);
      if (success) {
        localStorage.setItem('firebase_config', JSON.stringify(config));
        setIsDbConnected(true);
      } else {
        alert("Failed to initialize Firebase. Check that your config object is valid.");
