export const analyzeJob = async (job: Job): Promise<JobAnalysis> => {
  const ai = getClient();
  const safeSummary = (job.summary || "").substring(0, 5000);

  const prompt = `
    Analyze this job for the user (Vyom) based on the System Instructions provided. Address the user directly as "You".

    Job Details:
    Title: ${job.title}
    Company: ${job.company}
    Location: ${job.location}
    Description: ${safeSummary}

    ### SCORING PROTOCOL
    1. **Industry Boost**:
       - **+20 POINTS** if Fintech, Insurance, Banking, Investment, Wealth Management.
       - **+10 POINTS** if Public Sector, Government, High-Growth Tech, or Agency.
    2. **Seniority/Salary Check**:
       - If generic title (e.g., "Product Designer"), check for signs of seniority: salary > £45k, "lead", "manage", "own the process", "mentor". If found, treat as Senior (High Score).
       - If "0-2 years", "recent grad" -> Score < 20.

    ### EXTRACTION TASK
    - **Industry Category**: Classify the COMPANY into one of these buckets: "Fintech & Banking", "Insurance", "Public Sector", "Agency & Consulting", "Retail & E-commerce", "Media", "Energy", or "Tech & Product".
    - **Work Pattern**: Look for "Remote", "Hybrid", "On-site" and specific days.
    - **Experience**: Look for required years.
    - **Salary**: Look for pay ranges.

    ### STRATEGY & VERDICT RULES
    - **Verdict**: Punchy 1-sentence summary indicating why it fits YOUR background. (Use "You").
    - **Strategy**: YOU MUST Reference YOUR specific background:
       - If Design Systems -> Reference "Your Trove Design System experience at HES".
       - If Impact/Transformation -> Reference "Your Bronze Digital Impact Award with Stonewater".
       - If Compliance -> Reference "Your Intact Insurance compliance workflows".

    CHECK: Location/Commute.
    - If London/Manchester and requires "3+ days/week", set isCommuteRisk: true.

    Return a JSON object with this schema:
    {
      "score": number (0-100),
      "verdict": "string",
      "strategy": "string",
      "isHighValue": boolean,
      "isCommuteRisk": boolean,
      "matchedKeywords": ["string", "string"],
      "workPattern": "string",
      "experienceRequired": "string",
      "salary": "string",
      "industry": "string"
    }
  `;

  try {
    const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.0,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER },
            verdict: { type: Type.STRING },
            strategy: { type: Type.STRING },
            isHighValue: { type: Type.BOOLEAN },
            isCommuteRisk: { type: Type.BOOLEAN },
            workPattern: { type: Type.STRING },
            experienceRequired: { type: Type.STRING },
            salary: { type: Type.STRING },
            industry: { type: Type.STRING },
            matchedKeywords: { 
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          }
        }
      }
    }));

    const text = response.text || "{}";
    const cleanJson = text.replace(/```json/g, '').replace(/```/g, '').trim();

    return JSON.parse(cleanJson);
  } catch (error) {
    console.error("Error analyzing job:", error);
    return {
      score: 0,
      verdict: "Analysis failed",
      strategy: "Manual review required",
      isHighValue: false,
      isCommuteRisk: false,
      matchedKeywords: []
    };
  }
};

/**
 * Step 3: Generate Application Kit (Strategy, Resume Tips, Interview Prep, Cover Letter)
 */
export const generateApplicationKit = async (job: Job, analysis: JobAnalysis): Promise<string> => {
  const ai = getClient();

  const prompt = `
    Create a complete "Application Strategy Kit" for Vyom applying to:
    Role: ${job.title} at ${job.company}.

    Job Context: ${job.summary}
    Analysis: ${analysis.strategy}

    Output structured Markdown. Address Vyom as "You".
    Sections: Application Strategy, Resume Adjustments, Interview Prep, Draft Cover Letter.
  `;

  try {
    const response = await retryWithBackoff<GenerateContentResponse>(() => ai.models.generateContent({
      model: "gemini-3-pro-preview", 
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
      }
    }));

    return response.text || "Could not generate kit.";
  } catch (error) {
    console.error("Error generating kit:", error);
    return "# Error\nCould not generate application kit. Please try again.";
  }
};
