                    <textarea value={configInput} onChange={(e) => setConfigInput(e.target.value)} placeholder={`const firebaseConfig = { ... }`} className="w-full h-64 p-4 font-mono text-xs bg-gray-900 text-green-400 rounded-sm border focus:ring-2 focus:ring-[#86BC25] focus:outline-none"/>
                </div>
                <button onClick={handleConnectDb} className="w-full py-4 bg-black hover:bg-[#86BC25] text-white hover:text-black font-bold uppercase tracking-widest transition-all rounded-sm shadow-lg flex items-center justify-center gap-2">
                    Initialize System <Database size={18} />
                </button>
            </div>
        </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f3f4f6] font-sans text-gray-900 pb-20">
      <header className="bg-white border-b border-gray-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="bg-black p-2 rounded-sm text-white"><Zap size={20} fill="currentColor" className="text-[#86BC25]" /></div>
             <div>
                <h1 className="text-lg font-extrabold uppercase tracking-tighter leading-none">Vyom's Job Agent</h1>
                <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Cloud Connected</p>
             </div>
          </div>
          <div className="flex items-center gap-4">
            {analyzingCount > 0 && (
                <div className="flex items-center gap-2 px-3 py-1 bg-blue-50 text-blue-700 rounded-full text-xs font-bold uppercase tracking-wide border border-blue-100 animate-pulse">
                    <RefreshCw size={12} className="animate-spin" />
                    Analyzing {analyzingCount}...
                </div>
            )}

            {/* UPDATE BUTTON - NOW IN HEADER */}
            {allJobs.length > 0 && (
                <button 
                    onClick={handleUpdateAllJobs}
                    disabled={analyzingCount > 0}
                    className="flex items-center gap-2 px-4 py-2 bg-amber-400 text-black text-xs font-bold uppercase tracking-widest rounded-sm hover:bg-amber-500 shadow-md transition-colors disabled:opacity-50"
                >
                    <Sparkles size={14} />
                    {analyzingCount > 0 ? 'Updating...' : 'Update Data'}
                </button>
            )}

            <button onClick={fetchJobs} disabled={isFetching} className={`flex items-center gap-2 px-4 py-2 text-xs font-bold uppercase tracking-widest rounded-sm transition-all ${isFetching ? 'bg-gray-100 text-gray-400 cursor-not-allowed' : 'bg-black text-white hover:bg-[#86BC25] hover:text-black shadow-md'}`}>
                <Search size={14} />
                {isFetching ? 'Scouting...' : 'Scout Now'}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8 grid grid-cols-12 gap-8">
        <div className="col-span-12 lg:col-span-3 space-y-6">

            <div className="bg-white p-6 rounded-sm border border-gray-200 shadow-sm">
                <div className="flex items-center gap-2 mb-4 text-xs font-bold text-gray-400 uppercase tracking-widest"><Filter size={14} /> Filters</div>
                <div className="space-y-4">
                    <div>
                        <label className="block text-xs font-bold text-gray-800 uppercase mb-2">Location</label>
                        <div className="flex flex-wrap gap-2">
                            {filterOptions.map(city => {
                                const count = locationCounts[city] || 0;
                                if (count === 0 && city !== 'All') return null;
                                return (
                                    <button key={city} onClick={() => setCityFilter(city)} className={`px-3 py-1.5 text-[10px] font-bold uppercase tracking-wider border rounded-sm transition-colors ${cityFilter === city ? 'bg-black text-white border-black' : 'bg-white text-gray-600 border-gray-200 hover:border-gray-400'}`}>
                                        {city} ({count})
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-gray-800 uppercase mb-2">Sort By</label>
                        <div className="flex bg-gray-100 p-1 rounded-sm">
                             <button onClick={() => setSortBy('Score')} className={`flex-1 py-1.5 text-[10px] font-bold uppercase tracking-wider rounded-sm transition-all ${sortBy === 'Score' ? 'bg-white text-black shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>Score</button>
                             <button onClick={() => setSortBy('Date')} className={`flex-1 py-1.5 text-[10px] font-bold uppercase tracking-wider rounded-sm transition-all ${sortBy === 'Date' ? 'bg-white text-black shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>Date</button>
                        </div>
                    </div>
                </div>
            </div>
            <StatsPanel jobs={allJobs} />
        </div>

        <div className="col-span-12 lg:col-span-9">

            <div className="flex border-b border-gray-200 mb-6">
                <button onClick={() => setActiveTab('new')} className={`px-6 py-3 text-sm font-bold uppercase tracking-wide border-b-2 transition-colors flex items-center gap-2 ${activeTab === 'new' ? 'border-[#86BC25] text-black' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>
                    <Briefcase size={16} />
                    Your Pipeline ({allJobs.filter(j => (j.status || 'new') === 'new').length})
                </button>
                <button onClick={() => setActiveTab('applied')} className={`px-6 py-3 text-sm font-bold uppercase tracking-wide border-b-2 transition-colors flex items-center gap-2 ${activeTab === 'applied' ? 'border-[#86BC25] text-black' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>
                    <div className="w-4 h-4 bg-gray-200 rounded-full flex items-center justify-center text-[10px]">{allJobs.filter(j => j.status === 'applied').length}</div>
                    Applied
                </button>
            </div>
            <div className="space-y-4">
                {sortedJobs.length === 0 ? (
                    <div className="text-center py-20 bg-white border border-gray-200 rounded-sm">
                        <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4 text-gray-300"><Briefcase size={32} /></div>
                        <h3 className="text-lg font-bold text-black uppercase tracking-tight">No Active Opportunities</h3>
                        <p className="text-gray-500 text-sm mt-2">Adjust filters or run a new scout to populate your dashboard.</p>
                    </div>
                ) : (
                    sortedJobs.map(job => (
                        <JobCard key={job.id} job={job} onGenerateKit={handleDraftKit} onToggleStatus={toggleJobStatus} onDelete={handleDelete} />
                    ))
                )}
            </div>
            {sortedJobs.length > 0 && activeTab === 'new' && (
                <div className="flex justify-center mt-8">
                     <button onClick={fetchJobs} disabled={isFetching} className="px-8 py-4 bg-black text-white text-sm font-bold uppercase tracking-widest hover:bg-[#86BC25] hover:text-black transition-all shadow-lg flex items-center gap-3 rounded-sm">
                        <PlusCircle size={18} />
                        Scout More Roles
                     </button>
                </div>
            )}
        </div>
      </main>

      <CoverLetterModal isOpen={modalOpen} onClose={() => setModalOpen(false)} job={selectedJob} content={kitContent} isGenerating={isGeneratingKit} />
    </div>
  );
};

export default App;
